// Payload real enviado por core_app (server/services/notificationDispatcher.js).
// Tres formas posibles según "event": "test", "transfer_results", "critical_error".
// El texto usa *negrita* estilo Markdown, compatible tanto con Telegram
// (parse_mode: Markdown) como con el formato nativo de WhatsApp — por eso
// un solo mensaje sirve para ambos canales sin duplicar la lógica.
const body = $input.item.json.body ?? $input.item.json;
const event = body.event;

let text = "";

if (event === "transfer_results") {
  const runTypeLabel = body.runType === "automatic" ? "Automática" : "Manual";
  const icon = body.failedCount > 0 ? "⚠️" : "✅";
  text += `${icon} *Transferencias ${runTypeLabel}*\n\n`;
  text += `✅ Exitosas: ${body.successCount}\n`;
  text += `❌ Fallidas: ${body.failedCount}\n`;
  text += `📊 Total: ${body.totalCount}\n`;
  text += `🕐 Inicio: ${body.startTime}\n`;
  text += `🕑 Fin: ${body.endTime} (${body.durationLabel})\n`;
  if (body.scheduledHour) text += `⏰ Hora programada: ${body.scheduledHour}\n`;
  if (Array.isArray(body.errors) && body.errors.length > 0) {
    text += `\n*Errores:*\n`;
    text += body.errors.map((e) => `• ${e.name}: ${e.message}`).join("\n");
  }
} else if (event === "critical_error") {
  text += `🚨 *Error Crítico en Core App*\n\n${body.errorMessage}\n`;
  if (body.scheduledHour) text += `\nHora programada: ${body.scheduledHour}`;
  if (body.additionalInfo) text += `\nInfo adicional: ${body.additionalInfo}`;
} else if (event === "test") {
  text += `✅ *Prueba de conexión — Core App*\n${body.message}\nHora: ${body.timestamp}`;
} else {
  text += `ℹ️ Evento no reconocido de Core App:\n\`\`\`\n${JSON.stringify(body, null, 2)}\n\`\`\``;
}

return [{ json: { text } }];
